<script setup lang="ts">
import {ref,watch,onMounted,onUnmounted,nextTick} from 'vue';import axios from 'axios';import {useRoute,RouterLink} from 'vue-router';
import {realtimeStatus,type RealtimeUpdate} from './realtime';
const stream=ref<HTMLElement|null>(null),selfId=ref(0),focusedMessage=ref<number|null>(null);
const route=useRoute(),chats=ref<any[]>([]),messages=ref<any[]>([]),content=ref(''),error=ref(''),busy=ref(false),loading=ref(false);
let focusTimer:ReturnType<typeof setTimeout>|undefined,sequence=0,job:Promise<void>|undefined,dirty=false;
async function headers(){return {'X-XSRF-TOKEN':(await axios.get('/api/auth/csrf')).data.token};}
async function refresh(){try{chats.value=(await axios.get('/api/chats')).data;}catch{error.value='消息信息加载失败';}}
function syncMessages(){
 dirty=true;if(job)return job;const current=sequence,id=String(route.params.id);
 const task=(async()=>{loading.value=true;
  try{if(!selfId.value)selfId.value=(await axios.get('/api/people/me')).data.id;
   while(dirty&&current===sequence){dirty=false;const atBottom=!stream.value||stream.value.scrollHeight-stream.value.scrollTop-stream.value.clientHeight<80;let received=false;
    while(current===sequence){const {data}=await axios.get('/api/chats/'+id+'/messages',{params:{after:messages.value.at(-1)?.id||0}});if(current!==sequence)return;messages.value.push(...data);received ||= data.length>0;if(data.length<50)break;}
    if(current!==sequence)return;await nextTick();if(atBottom&&stream.value)stream.value.scrollTop=stream.value.scrollHeight;
    if(received){await axios.post('/api/chats/'+id+'/read',null,{params:{through:messages.value.at(-1).id},headers:await headers()});await refresh();}
   }
  }catch{if(current===sequence)error.value='消息加载失败，请重试或检查连接';}finally{if(current===sequence){loading.value=false;job=undefined;}}
 })();job=task;return task;
}
async function send(){busy.value=true;error.value='';try{await axios.post('/api/chats/'+route.params.id+'/messages',{content:content.value},{headers:await headers()});content.value='';await syncMessages();}catch{error.value='发送失败，请重试';}finally{busy.value=false;}}
async function openChat(){sequence++;const current=sequence;job=undefined;dirty=false;messages.value=[];error.value='';focusedMessage.value=null;if(focusTimer)clearTimeout(focusTimer);await syncMessages();if(current!==sequence)return;
 const focus=Number(route.query.focus);if(!Number.isSafeInteger(focus)||focus<=0)return;await nextTick();const el=stream.value?.querySelector<HTMLElement>('[data-chat-message-id="'+focus+'"]');if(!el){error.value='对应历史消息未找到，已打开原私聊。';return;}el.scrollIntoView({behavior:'instant',block:'center'});focusedMessage.value=focus;focusTimer=setTimeout(()=>focusedMessage.value=null,2400);
}
function realtime(event:Event){const update=(event as CustomEvent<RealtimeUpdate>).detail;if(update.kind==='resync'||update.kind==='chat'&&String(update.chatId)===String(route.params.id)){syncMessages();refresh();}}
watch(()=>[route.params.id,route.query.focus,route.query._jump],openChat,{immediate:true});
onMounted(()=>{refresh();window.addEventListener('realtime-update',realtime);});
onUnmounted(()=>{window.removeEventListener('realtime-update',realtime);if(focusTimer)clearTimeout(focusTimer);sequence++;});
</script><template><section class="messages"><RouterLink to="/notifications">← 消息中心</RouterLink><h1>私聊</h1><p class="connection-status" role="status">{{realtimeStatus==='connected'?'实时连接已建立':realtimeStatus==='reconnecting'?'连接中断，正在重连…':'正在连接实时消息…'}}</p><p v-if="error" role="alert">{{error}} <button @click="error='';syncMessages()">重试</button></p><div class="chat-layout"><main v-if="route.params.id"><header><RouterLink v-if="chats.find(c=>String(c.id)===String(route.params.id))" :to="'/people/'+chats.find(c=>String(c.id)===String(route.params.id)).peerId">{{chats.find(c=>String(c.id)===String(route.params.id)).peerName}} · 查看主页 ↗</RouterLink></header><div ref="stream" class="chat-stream"><article v-for="m in messages" :key="m.id" :data-chat-message-id="m.id" :class="{mine:m.senderId===selfId,'chat-focused':focusedMessage===m.id}"><RouterLink :to="'/people/'+m.senderId"><img :src="'/api/conversations/avatars/'+m.senderId" alt="发言者头像"></RouterLink><div><strong>{{m.username}}</strong><time>{{m.createdAt}}</time><p>{{m.content}}</p></div></article><p v-if="!messages.length">开始你们的校园对话。</p></div><form @submit.prevent="send"><textarea v-model="content" required maxlength="2000" placeholder="询问商品、约定线下交接…"></textarea><div><button v-for="emoji in ['😊','👍','🙏']" type="button" @click="content+=emoji">{{emoji}}</button><button :disabled="busy||!content.trim()">{{busy?'发送中…':'发送'}}</button></div></form></main><main v-else>选择一位同学开始聊天。</main></div></section></template><style scoped>.messages{flex:1;background:#f6f4ee;color:#293d3b;padding:30px 5%}h1{font-size:30px;margin:10px 0 25px}.chat-layout{display:grid;grid-template-columns:minmax(0,1fr);gap:20px}main{background:white;padding:20px;border-radius:12px;min-width:0}article img{width:35px;height:35px;border-radius:50%;object-fit:cover}header a{color:#94744c;font-size:13px}.chat-stream{max-height:52vh;overflow:auto;padding:12px 0}article{display:flex;gap:12px;margin:20px 0}article>div{max-width:78%;background:#f5f3eb;border-radius:0 10px 10px;padding:15px;min-width:0}strong{font-size:12px}time{font-size:10px;color:#8c927d;margin-left:15px}article p{white-space:pre-wrap;overflow-wrap:anywhere;font-size:14px;line-height:1.8}textarea{width:100%;min-height:80px;border:1px solid #dde0d4;border-radius:6px;font:inherit;padding:12px}button{background:#304b49;color:white;border:0;border-radius:4px;padding:9px 15px;margin:10px 8px 0 0;cursor:pointer}button:disabled{opacity:.5}@media(max-width:700px){.chat-layout{grid-template-columns:1fr}}article.mine{flex-direction:row-reverse}article.mine>div{background:#e5eddc;border-radius:10px 0 10px 10px}.mine strong{color:#365448}article>div p{margin-bottom:0}@media(max-width:500px){article>div{max-width:82%}time{display:block;margin:5px 0 0}}.chat-focused>div{box-shadow:inset 0 2px 6px #26352d44,0 0 0 2px #c4ac7a;animation:chat-press 2.4s ease}.chat-focused{scroll-margin:20px}@keyframes chat-press{15%,75%{transform:scale(.985)}100%{transform:scale(1)}}@media(prefers-reduced-motion:reduce){.chat-focused>div{animation:none}}.connection-status{font-size:12px;color:#78836f;margin-bottom:20px}</style>
